def _correo_valido(email: str) -> bool:
    clean = (email or "").strip().lower()
    if not clean or "@" not in clean or "\r" in clean or "\n" in clean:
        return False
    local, _, domain = clean.partition("@")
    if not local or not domain or "." not in domain:
        return False
    if clean in DUMMY_RECIPIENTS or any(clean.endswith(s) for s in DUMMY_SUFFIXES):
        return False
    return True


def marcar_usuarios_existentes_verificados(apps, schema_editor):
    User = apps.get_model("usuarios", "User")
